"""Engine factory, SQLite safety pragmas, ``init_db`` and the ``get_db`` dependency."""

import logging
from collections.abc import Iterator
from functools import cached_property
from pathlib import Path
from typing import Any

from fastapi import Request
from sqlalchemy import Engine, create_engine, event
from sqlalchemy.engine import make_url
from sqlalchemy.orm import Session, sessionmaker
from sqlalchemy.pool import StaticPool

from app.db.base import Base

logger = logging.getLogger(__name__)

BUSY_TIMEOUT_MS = 5000


def _is_memory(database: str | None) -> bool:
    return database in (None, "", ":memory:") or bool(
        database and database.startswith("file::memory:")
    )


def _set_sqlite_pragmas(dbapi_connection: Any, in_memory: bool) -> None:
    cursor = dbapi_connection.cursor()
    try:
        cursor.execute("PRAGMA foreign_keys=ON")
        cursor.execute(f"PRAGMA busy_timeout={BUSY_TIMEOUT_MS}")
        cursor.execute("PRAGMA synchronous=NORMAL")
        if not in_memory:
            cursor.execute("PRAGMA journal_mode=WAL")
    finally:
        cursor.close()


def create_db_engine(url: str) -> Engine:
    """Create a SQLite engine with safety pragmas applied on every connection."""
    parsed = make_url(url)
    if parsed.get_backend_name() != "sqlite":
        raise ValueError("Only SQLite database URLs are supported")
    in_memory = _is_memory(parsed.database)
    kwargs: dict[str, Any] = {"connect_args": {"check_same_thread": False}}
    if in_memory:
        kwargs["poolclass"] = StaticPool  # one shared connection so :memory: survives sessions
    else:
        Path(parsed.database).expanduser().resolve().parent.mkdir(parents=True, exist_ok=True)
    engine = create_engine(url, **kwargs)

    @event.listens_for(engine, "connect")
    def _on_connect(dbapi_connection: Any, _record: Any) -> None:
        _set_sqlite_pragmas(dbapi_connection, in_memory)

    return engine


def init_db(engine: Engine) -> None:
    """Create missing tables, then add missing nullable columns/indexes to existing ones.

    There is no Alembic in this PoC: ``sync_schema`` keeps an existing database (for example a
    Docker volume from an earlier phase) working. See ``app.db.migrate``.
    """
    from app.db import models  # noqa: F401  (register models on Base.metadata)
    from app.db.migrate import sync_schema

    Base.metadata.create_all(engine)
    sync_schema(engine)


def drop_all(engine: Engine) -> None:
    from app.db import models  # noqa: F401

    Base.metadata.drop_all(engine)


class Database:
    """Lazy holder for the engine and session factory (nothing touches disk until used)."""

    def __init__(self, url: str) -> None:
        self.url = url

    @cached_property
    def engine(self) -> Engine:
        return create_db_engine(self.url)

    @cached_property
    def session_factory(self) -> sessionmaker[Session]:
        return sessionmaker(self.engine, expire_on_commit=False)

    def init_db(self) -> None:
        init_db(self.engine)

    def dispose(self) -> None:
        if "engine" in self.__dict__:
            self.engine.dispose()


def get_db(request: Request) -> Iterator[Session]:
    """FastAPI dependency: one session per request, always closed."""
    database: Database = request.app.state.database
    session = database.session_factory()
    try:
        yield session
    finally:
        session.close()
"""Additive schema sync for existing SQLite files (no Alembic in this PoC).

``Base.metadata.create_all`` only creates *missing tables*. A Docker volume that already holds a
database from an earlier phase would therefore never receive columns added later, and the API
would fail on the first query that names them. ``sync_schema`` runs right after ``create_all``
and, for tables that already exist, adds what the models declare but the file lacks:

* columns: only when SQLite can add them safely, i.e. NULLABLE (or with a server default) and
  neither primary key nor unique. ``ALTER TABLE ... ADD COLUMN`` keeps every existing row.
* indexes: non-unique or unique indexes declared on the models whose columns all exist.

Anything that cannot be done additively (a NOT NULL column without a default, a new unique
column, a changed type, a dropped column) is *refused*: a clear error is logged and the rest of
the sync carries on. Nothing here ever raises into application start-up.
"""

import logging
from dataclasses import dataclass, field

from sqlalchemy import Column, Engine, MetaData, Table, inspect, text
from sqlalchemy.exc import SQLAlchemyError
from sqlalchemy.schema import CreateIndex

from app.db.base import Base

logger = logging.getLogger(__name__)


@dataclass
class SyncReport:
    added_columns: list[str] = field(default_factory=list)  # "table.column"
    added_indexes: list[str] = field(default_factory=list)
    refused: list[str] = field(default_factory=list)  # human-readable reasons

    @property
    def changed(self) -> bool:
        return bool(self.added_columns or self.added_indexes)


def _quote(name: str) -> str:
    return '"' + name.replace('"', '""') + '"'


def _refusal_reason(column: Column) -> str | None:
    """Why ``column`` cannot be added with ``ALTER TABLE ADD COLUMN`` (None = it can)."""
    if column.primary_key:
        return "it is a primary key"
    if column.unique:
        return "it is unique"
    if not column.nullable and column.server_default is None:
        return "it is NOT NULL without a server default (existing rows would violate it)"
    return None


def _column_ddl(engine: Engine, table: Table, column: Column) -> str:
    parts = [
        f"ALTER TABLE {_quote(table.name)} ADD COLUMN {_quote(column.name)}",
        column.type.compile(dialect=engine.dialect),
    ]
    if column.server_default is not None:
        default_text = getattr(column.server_default.arg, "text", column.server_default.arg)
        parts.append(f"DEFAULT {default_text}")
    if not column.nullable:
        parts.append("NOT NULL")
    for fk in column.foreign_keys:
        target = fk.column
        parts.append(f"REFERENCES {_quote(target.table.name)} ({_quote(target.name)})")
    return " ".join(parts)


def sync_schema(engine: Engine, metadata: MetaData | None = None) -> SyncReport:
    """Add missing nullable columns and indexes to existing tables; never raises.

    ``metadata`` defaults to the application's models (a parameter only so tests can use their
    own tables).
    """
    report = SyncReport()
    try:
        inspector = inspect(engine)
        for table in (metadata or Base.metadata).sorted_tables:
            if not inspector.has_table(table.name):
                continue  # create_all makes new tables with everything on them
            existing = {c["name"] for c in inspector.get_columns(table.name)}
            for column in table.columns:
                if column.name in existing:
                    continue
                label = f"{table.name}.{column.name}"
                reason = _refusal_reason(column)
                if reason is not None:
                    message = f"Cannot add column {label} additively: {reason}"
                    logger.error("Schema sync refused: %s", message)
                    report.refused.append(message)
                    continue
                try:
                    with engine.begin() as conn:
                        conn.execute(text(_column_ddl(engine, table, column)))
                except SQLAlchemyError:
                    message = f"Adding column {label} failed"
                    logger.exception("Schema sync failed: %s", message)
                    report.refused.append(message)
                    continue
                existing.add(column.name)
                report.added_columns.append(label)
                logger.info("Schema sync: added column %s", label)

            present_indexes = {ix["name"] for ix in inspect(engine).get_indexes(table.name)}
            for index in sorted(table.indexes, key=lambda i: i.name or ""):
                if index.name in present_indexes:
                    continue
                if not all(c.name in existing for c in index.columns):
                    continue  # its column was refused above
                try:
                    with engine.begin() as conn:
                        conn.execute(CreateIndex(index))
                except SQLAlchemyError:
                    message = f"Adding index {index.name} failed"
                    logger.exception("Schema sync failed: %s", message)
                    report.refused.append(message)
                    continue
                report.added_indexes.append(str(index.name))
                logger.info("Schema sync: added index %s", index.name)
    except Exception:  # never let a schema-sync bug stop the API from starting
        logger.exception("Schema sync failed unexpectedly; continuing without it")
    return report
from fastapi import APIRouter

from app.api.routes import auth, chat

api_router = APIRouter(prefix="/api")
api_router.include_router(auth.router)
api_router.include_router(chat.router)
"""Provider dependencies backed by ``app.state`` (built lazily, overridable in tests)."""

import logging

from fastapi import Request

from app.chat.fallbacks import UnavailableAdapter, UnavailableLLM
from app.integrations.base import SubmissionAdapter
from app.integrations.factory import build_submission_adapter
from app.llm.base import LLMProvider
from app.llm.factory import build_llm_provider

logger = logging.getLogger(__name__)


def get_llm_provider(request: Request) -> LLMProvider:
    """The LLM provider: the one passed to ``create_app`` or built once from the settings.

    A construction failure (for example a missing API key) is logged and replaced with a
    provider that raises ``LLMError``, so the chat degrades gracefully instead of crashing.
    """
    state = request.app.state
    if state.llm_provider is None:
        with state.provider_lock:
            if state.llm_provider is None:
                try:
                    state.llm_provider = build_llm_provider(state.settings)
                except Exception:
                    logger.exception("Could not build the LLM provider; chat will report it")
                    state.llm_provider = UnavailableLLM()
    return state.llm_provider


def get_submission_adapter(request: Request) -> SubmissionAdapter:
    state = request.app.state
    if state.submission_adapter is None:
        with state.provider_lock:
            if state.submission_adapter is None:
                try:
                    state.submission_adapter = build_submission_adapter(state.settings)
                except Exception:
                    logger.exception("Could not build the submission adapter")
                    state.submission_adapter = UnavailableAdapter()
    return state.submission_adapter
"""Employee chat endpoints (mounted under /api/chat). Contract: docs/chat-api-contract.md."""

import logging

from fastapi import APIRouter, Depends, HTTPException, Request, Response, status
from fastapi.responses import JSONResponse
from sqlalchemy.exc import SQLAlchemyError
from sqlalchemy.orm import Session

from app.api.deps import get_llm_provider, get_submission_adapter
from app.auth.dependencies import require_roles
from app.chat.actions import StaleCardError
from app.chat.service import ChatService, ConversationConflict, ConversationNotFound
from app.db.models import User
from app.db.session import get_db
from app.domain.enums import UserRole
from app.integrations.base import SubmissionAdapter
from app.llm.base import LLMProvider
from app.schemas.chat import (
    ActionBody,
    ConversationDetail,
    ConversationList,
    ConversationSummary,
    MessageBody,
    TurnResponse,
)

logger = logging.getLogger(__name__)

router = APIRouter(prefix="/chat", tags=["chat"])
Employee = Depends(require_roles(UserRole.EMPLOYEE))


def get_chat_service(
    db: Session = Depends(get_db),
    user: User = Employee,
    llm: LLMProvider = Depends(get_llm_provider),
    adapter: SubmissionAdapter = Depends(get_submission_adapter),
) -> ChatService:
    return ChatService(db, user, llm, adapter)


def _not_found() -> HTTPException:
    return HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Conversation not found")


def _db_unavailable() -> JSONResponse:
    return JSONResponse(
        status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
        content={"detail": "The database is temporarily unavailable. Please try again."},
    )


@router.get("/conversations", response_model=ConversationList)
def list_conversations(service: ChatService = Depends(get_chat_service)) -> ConversationList:
    return ConversationList(items=service.list_conversations())


@router.post(
    "/conversations", response_model=ConversationSummary, status_code=status.HTTP_201_CREATED
)
def create_conversation(service: ChatService = Depends(get_chat_service)) -> ConversationSummary:
    return service.create_conversation()


@router.get("/conversations/{conversation_id}", response_model=ConversationDetail)
def get_conversation(
    conversation_id: int, service: ChatService = Depends(get_chat_service)
) -> ConversationDetail:
    try:
        return service.get_conversation(conversation_id)
    except ConversationNotFound:
        raise _not_found() from None


@router.post("/conversations/{conversation_id}/messages", response_model=TurnResponse)
def post_message(
    conversation_id: int,
    body: MessageBody,
    request: Request,
    service: ChatService = Depends(get_chat_service),
) -> Response | TurnResponse:
    limit = request.app.state.settings.chat_max_message_chars
    if len(body.content) > limit:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,
            detail=f"Message is too long (maximum {limit} characters).",
        )
    if not body.content.strip():
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT, detail="Message must not be blank."
        )
    try:
        return service.post_message(conversation_id, body.content)
    except ConversationNotFound:
        raise _not_found() from None
    except ConversationConflict:
        return JSONResponse(
            status_code=status.HTTP_409_CONFLICT,
            content={"detail": "The conversation changed while I was working. Please try again."},
        )
    except SQLAlchemyError:
        logger.exception("Database error while handling a chat message")
        return _db_unavailable()


@router.post("/conversations/{conversation_id}/actions", response_model=TurnResponse)
def post_action(
    conversation_id: int,
    body: ActionBody,
    service: ChatService = Depends(get_chat_service),
) -> Response | TurnResponse:
    try:
        return service.post_action(conversation_id, body.card_id, body.action)
    except ConversationNotFound:
        raise _not_found() from None
    except StaleCardError as exc:
        return JSONResponse(
            status_code=status.HTTP_409_CONFLICT,
            content={"detail": str(exc), "warning_code": "stale_card"},
        )
    except SQLAlchemyError:
        logger.exception("Database error while handling a card action")
        return _db_unavailable()
import logging
import threading
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager

from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware

from app.api.router import api_router
from app.auth.csrf import CSRFMiddleware
from app.auth.tokens import resolve_jwt_secret
from app.config import Settings, get_settings
from app.db.session import Database
from app.integrations.base import SubmissionAdapter
from app.llm.base import LLMProvider
from app.seed import seed_demo_data

logger = logging.getLogger(__name__)


def startup_database(database: Database, settings: Settings) -> None:
    """Create tables and (optionally) seed. Failures are logged, never raised."""
    try:
        database.init_db()
    except Exception:
        logger.exception("Database initialisation failed; the API will start without it")
        return
    if not settings.db_auto_seed:
        return
    try:
        with database.session_factory() as session:
            result = seed_demo_data(session)
        if result.seeded:
            logger.info("Seeded fictional demo data")
    except Exception:
        logger.exception("Demo data seeding failed; continuing without it")


def create_app(
    settings: Settings | None = None,
    database: Database | None = None,
    llm_provider: LLMProvider | None = None,
    submission_adapter: SubmissionAdapter | None = None,
) -> FastAPI:
    """Build the app. Providers default to the configured ones (built lazily on first use, see
    ``app.api.deps``); tests pass doubles or use ``dependency_overrides``."""
    settings = settings or get_settings()
    jwt_secret = resolve_jwt_secret(settings)  # raises in production without a strong secret
    database = database or Database(settings.database_url)

    @asynccontextmanager
    async def lifespan(_: FastAPI) -> AsyncIterator[None]:
        startup_database(database, settings)
        yield
        database.dispose()

    app = FastAPI(title="SCMP Internal Operations AI Assistant (PoC)", lifespan=lifespan)
    app.state.settings = settings
    app.state.database = database
    app.state.jwt_secret = jwt_secret
    app.state.llm_provider = llm_provider
    app.state.submission_adapter = submission_adapter
    app.state.provider_lock = threading.Lock()
    # Middleware added last is outermost: CORS wraps CSRF, so a 403 "CSRF check failed" from an
    # allowed origin still carries the CORS headers and preflights never reach the CSRF check.
    app.add_middleware(CSRFMiddleware, allowed_origins=list(settings.cors_origins))
    app.add_middleware(
        CORSMiddleware,
        allow_origins=list(settings.cors_origins),
        allow_credentials=True,
        allow_methods=["*"],
        allow_headers=["Authorization", "Content-Type", "Accept", "X-Requested-With"],
    )

    @app.get("/health")
    def health() -> dict[str, str]:
        return {"status": "ok"}

    app.include_router(api_router)
    return app


app = create_app()

